WITH source AS (SELECT ?1 AS body), checked AS (SELECT body,json_type(body) AS kind,CASE WHEN json_type(body)='text' THEN 1 WHEN json_type(body)='array' THEN NOT EXISTS(SELECT 1 FROM json_each(body) WHERE type<>'text') ELSE 0 END AS valid FROM source) SELECT kind,CASE WHEN valid=1 THEN CASE WHEN kind='text' THEN json_extract(body,'$') ELSE (SELECT coalesce(group_concat(value,''),'') FROM (SELECT value FROM json_each(body) ORDER BY CAST(key AS INTEGER))) END ELSE NULL END AS text FROM checked;
